basic.fetcher:
(async function (args, reqOptions) {
  const reqOptions1 = await BeaconBar.executeFunction("reqOptions")();
  return {
    url: `${reqOptions1}Widgets/Payslip/InitPaySlipData`,
    method: "GET",
    headers: {
      "x-requested-with": "XMLHttpRequest",
    },
    params: new URLSearchParams({
      "_": "1761809298751",
    })
  };
})

basic.transformer:
(function (data, args, reqOptions) {
  return data.PayYears.flatMap(y =>
    y.PayPeriods.map(p => ({
      PFCode: data.PFCode,
      Year: y.Year,
      Schedule: p.Schedule,
      Period: p.Period
    }))
  );
})

